return {["scripts/actions/abilities/dodge.lua"]={["Path"]="scripts/actions/abilities/dodge.lua",["SHA256"]="ea953c732ad846d69a2794ab8ffeb6a8d9504fb42e2fdee91116080777717620",["Text"]="-----------------------------------\n-- Ability: Dodge\n-- Enhances user's evasion.\n-- Obtained: Monk Level 15\n-- Recast Time: 5:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.monk.useDodge(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/double-up.lua"]={["Path"]="scripts/actions/abilities/double-up.lua",["SHA256"]="7de1aed874bd3707cda722020f9b15adfeb77e5647103d4cabb2d1f9ed23a72e",["Text"]="-----------------------------------\n-- Ability: Double Up\n-- Enhances an active Phantom Roll effect that is eligible for Double-Up.\n-- Obtained: Corsair Level 5\n-- Recast Time: 8 seconds\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkDoubleUp(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.useDoubleUp(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/double_shot.lua"]={["Path"]="scripts/actions/abilities/double_shot.lua",["SHA256"]="b3367c4b93ff81182b4b8aa89795800f63dfc114b3bee9087ffe4095f8ded656",["Text"]="-----------------------------------\n-- Ability: Double Shot\n-- Occasionally uses two units of ammunition to deal double damage.\n-- Obtained: Ranger Level 79\n-- Recast Time: 3:00\n-- Duration: 1:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkDoubleShot(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useDoubleShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/drachen_roll.lua"]={["Path"]="scripts/actions/abilities/drachen_roll.lua",["SHA256"]="d1dc98f6e0df063a9c446bf54da90b19ca75f6f17545f414e8ccbf34e0dd9947",["Text"]="-----------------------------------\n-- Ability: Drachen Roll\n-- Enhances pet accuracy for party members within area of effect\n-- Optimal Job: Dragoon\n-- Lucky Number: 4\n-- Unlucky Number: 8\n-- Level: 23\n-- Phantom Roll +1 Value: 5\n--\n-- Die Roll    |No DRG  |With DRG\n-- --------    -------  -----------\n-- 1           |+10     |+25\n-- 2           |+13     |+28\n-- 3           |+15     |+30\n-- 4           |+40     |+55\n-- 5           |+18     |+33\n-- 6           |+20     |+35\n-- 7           |+25     |+40\n-- 8           |+5      |+20\n-- 9           |+28     |+43\n-- 10          |+30     |+45\n-- 11          |+50     |+65\n-- Bust        |-15     |-15\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/dragon_breaker.lua"]={["Path"]="scripts/actions/abilities/dragon_breaker.lua",["SHA256"]="ec9df540cd4fd5ad0e3a8b001933369c8faf4a3cb229bc47bd99b9a35dce14a6",["Text"]="-----------------------------------\n-- Ability: Dragon Breaker\n-- Description: Lowers accuracy, evasion, magic accuracy, magic evasion and TP gain for dragons.\n-- Obtained: DRG Level 87\n-- Recast Time: 00:05:00\n-- Duration: 00:03:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.dragoon.useDragonBreaker(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/drain_samba.lua"]={["Path"]="scripts/actions/abilities/drain_samba.lua",["SHA256"]="f93436cc07b85f3486bc3e0aabcf7f1d4d8b023072b6f49fde914452b8507b26",["Text"]="-----------------------------------\n-- Ability: Drain Samba\n-- Inflicts the next target you strike with Drain daze, allowing all those engaged in battle with it to drain its HP.\n-- Obtained: Dancer Level 5\n-- TP Required: 10%\n-- Recast Time: 1:00\n-- Duration: 2:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FAN_DANCE) then\n        return xi.msg.basic.UNABLE_TO_USE_JA2, 0\n    elseif player:getTP() < 100 then\n        return xi.msg.basic.NOT_ENOUGH_TP, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- Only remove TP if the player doesn't have Trance.\n    if not player:hasStatusEffect(xi.effect.TRANCE) then\n        player:delTP(100)\n    end\n\n    local duration = 120 + player:getMod(xi.mod.SAMBA_DURATION) + (player:getJobPointLevel(xi.jp.SAMBA_DURATION) * 2)\n    duration       = duration * (100 + player:getMod(xi.mod.SAMBA_PDURATION)) / 100\n\n    player:delStatusEffect(xi.effect.HASTE_SAMBA)\n    player:delStatusEffect(xi.effect.ASPIR_SAMBA)\n    player:addStatusEffect(xi.effect.DRAIN_SAMBA, { power = 1, duration = duration, origin = player })\n\n    return xi.effect.DRAIN_SAMBA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/drain_samba_ii.lua"]={["Path"]="scripts/actions/abilities/drain_samba_ii.lua",["SHA256"]="faeabc02698f0f716bac788bb2f0ff0c8dd3f0002969c21db15190a7517f75e0",["Text"]="-----------------------------------\n-- Ability: Drain Samba II\n-- Inflicts the next target you strike with Drain Daze, allowing all those engaged in battle with it to drain its HP.\n-- Obtained: Dancer Level 35\n-- TP Required: 25%\n-- Recast Time: 1:00\n-- Duration: 1:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FAN_DANCE) then\n        return xi.msg.basic.UNABLE_TO_USE_JA2, 0\n    elseif player:getTP() < 250 then\n        return xi.msg.basic.NOT_ENOUGH_TP, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- Only remove TP if the player doesn't have Trance.\n    if not player:hasStatusEffect(xi.effect.TRANCE) then\n        player:delTP(250)\n    end\n\n    local duration = 120 + player:getMod(xi.mod.SAMBA_DURATION) + (player:getJobPointLevel(xi.jp.SAMBA_DURATION) * 2)\n    duration       = duration * (100 + player:getMod(xi.mod.SAMBA_PDURATION)) / 100\n    player:delStatusEffect(xi.effect.HASTE_SAMBA)\n    player:delStatusEffect(xi.effect.ASPIR_SAMBA)\n    player:addStatusEffect(xi.effect.DRAIN_SAMBA, { power = 2, duration = duration, origin = player })\n\n    return xi.effect.DRAIN_SAMBA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/drain_samba_iii.lua"]={["Path"]="scripts/actions/abilities/drain_samba_iii.lua",["SHA256"]="88269871009a50f50af0551bd6333f10250796bec5b64ffc754643acd18b079d",["Text"]="-----------------------------------\n-- Ability: Drain Samba III\n-- Inflicts the next target you strike with Drain daze, allowing party members engaged in battle with it to drain its HP.\n-- Obtained: Dancer Level 65\n-- TP Required: 40%\n-- Recast Time: 1:00\n-- Duration: 1:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.FAN_DANCE) then\n        return xi.msg.basic.UNABLE_TO_USE_JA2, 0\n    elseif player:getTP() < 400 then\n        return xi.msg.basic.NOT_ENOUGH_TP, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    -- Only remove TP if the player doesn't have Trance.\n    if not player:hasStatusEffect(xi.effect.TRANCE) then\n        player:delTP(400)\n    end\n\n    local duration = 120 + player:getMod(xi.mod.SAMBA_DURATION) + (player:getJobPointLevel(xi.jp.SAMBA_DURATION) * 2)\n    duration       = duration * (100 + player:getMod(xi.mod.SAMBA_PDURATION)) / 100\n    player:delStatusEffect(xi.effect.HASTE_SAMBA)\n    player:delStatusEffect(xi.effect.ASPIR_SAMBA)\n    player:addStatusEffect(xi.effect.DRAIN_SAMBA, { power = 3, duration = duration, origin = player })\n\n    return xi.effect.DRAIN_SAMBA\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/eagle_eye_shot.lua"]={["Path"]="scripts/actions/abilities/eagle_eye_shot.lua",["SHA256"]="916a714ea3b40553ff4d9c6697f12cd5c693aa6cab342b450ccd28ae7e691bdb",["Text"]="-----------------------------------\n-- Ability: Eagle Eye Shot\n-- Delivers a powerful and accurate ranged attack.\n-- Obtained: Ranger Level 1\n-- Recast Time: 1:00:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.ranger.checkEagleEyeShot(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.ranger.useEagleEyeShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/earth_maneuver.lua"]={["Path"]="scripts/actions/abilities/earth_maneuver.lua",["SHA256"]="055e62f0b6524c26f357a99d524c086a908b06ca02ecb6cb24daf2477b2f17ac",["Text"]="-----------------------------------\n-- Ability: Earth Maneuver\n-- Enhances the effect of earth attachments. Must have animator equipped.\n-- Obtained: Puppetmaster level 1\n-- Recast Time: 10 seconds (shared with all maneuvers)\n-- Duration: 1 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.automaton.onManeuverCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.automaton.onUseManeuver(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/earth_shot.lua"]={["Path"]="scripts/actions/abilities/earth_shot.lua",["SHA256"]="ad0c19fa6677713837b1c6032f10ec02aa2db7fbccea594a1e5a54f76f1dea91",["Text"]="-----------------------------------\n-- Ability: Earth Shot\n-- Consumes an Earth Card to enhance earth-based debuffs. Deals earth-based magic damage\n-- Rasp Effect: Enhanced DoT and DEX-, Slow Effect +10%\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.checkQuickDraw(player, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.corsair.useElementalShot(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/ebullience.lua"]={["Path"]="scripts/actions/abilities/ebullience.lua",["SHA256"]="5dc32a2526c9b32ed9fc2fac2b9ba41c710ee7aed7c7150ce706bea718fa070e",["Text"]="-----------------------------------\n-- Ability: Ebullience\n-- Enhances the potency of your next black magic spell.\n-- Obtained: Scholar Level 55\n-- Recast Time: Stratagem Charge\n-- Duration: 1 black magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.EBULLIENCE) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.EBULLIENCE, { power = 1, duration = 60, origin = player })\n\n    return xi.effect.EBULLIENCE\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/ecliptic_attrition.lua"]={["Path"]="scripts/actions/abilities/ecliptic_attrition.lua",["SHA256"]="fb8331c86b249678a7f8cd57690eb9c9042a311a356dd758b24db65a8dfb3220",["Text"]="-----------------------------------\n-- Ability: Ecliptic Attrition\n-- Enhances the effects of your luopan.\n-- Increases the rate at which your luopan consumes its HP.\n-- Obtained: Geomancer Level 25\n-- Recast Time: 00:05:00\n-- Duration: N/A\n-- Notes: Luopan Potency +25%\n-- Base HP drain rate is 24HP/tic. With Ecliptic attrition it is 30HP/tic.\n-- Operates on a shared recast timer with Lasting Emanation\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.geomancer.geoOnEclipticAttritionCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    xi.job_utils.geomancer.eclipticAttrition(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/efflux.lua"]={["Path"]="scripts/actions/abilities/efflux.lua",["SHA256"]="b227309dfbee9cdfa184e85333deb3463f2fc5a415fb68e2c6ee819b986bf2fd",["Text"]="-----------------------------------\n-- Ability: Efflux\n-- Description: If the next spell you cast is a \"physical\" Blue magic spell, a TP bonus will be granted.\n-- Obtained: BLU Level 83\n-- Recast Time: 00:03:00\n-- Duration: 00:01:00 or first blue magic cast\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    xi.job_utils.blue_mage.checkEfflux(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.blue_mage.useEfflux(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/elemental_seal.lua"]={["Path"]="scripts/actions/abilities/elemental_seal.lua",["SHA256"]="bfff71671dacd508ca4bb8c85122e6d5395530e564ce792e32d048d3b8a66119",["Text"]="-----------------------------------\n-- Ability: Elemental Seal\n-- Enhances the accuracy of the user's next spell\n-- Obtained: Black Mage Level 15\n-- Recast Time: 10:00\n-- Duration: 1 Spell or 60 seconds, whichever occurs first.\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.black_mage.useElementalSeal(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/elemental_sforzo.lua"]={["Path"]="scripts/actions/abilities/elemental_sforzo.lua",["SHA256"]="091cb97ae7153fd72c5faef5e93ed79273da6efbcfc2c2af81e2dd0b99dccb6d",["Text"]="-----------------------------------\n-- Ability: Elemental Sforzo\n-- Grants immunity to all magic attacks.\n-- Obtained: Rune Fencer Level 1\n-- Recast Time: 1:00:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    ability:setRecast(math.max(0, ability:getRecast() - player:getMod(xi.mod.ONE_HOUR_RECAST) * 60))\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.ELEMENTAL_SFORZO, { power = 1, duration = 30, origin = player })\n\n    return xi.effect.ELEMENTAL_SFORZO\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/elemental_siphon.lua"]={["Path"]="scripts/actions/abilities/elemental_siphon.lua",["SHA256"]="dd75f843272c12d92e829c8907d56662988f2a697b319efc0b7072d2ade40235",["Text"]="-----------------------------------\n-- Ability: Elemental Siphon\n-- Drains MP from your summoned spirit.\n-- Obtained: Summoner level 50\n-- Recast Time: 5:00\n-- Duration: Instant\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    local pet = player:getPet()\n    local petID = 0\n\n    if pet then\n        petID = pet:getPetID()\n\n        if petID >= xi.petId.FIRE_SPIRIT and petID <= xi.petId.DARK_SPIRIT then -- spirits\n            return 0, 0\n        end\n    end\n\n    return xi.msg.basic.UNABLE_TO_USE_JA, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local spirit = player:getPet()\n    if not spirit then\n        return 0\n    end\n\n    local spiritElement = spirit:getPetID() + 1\n    if not spiritElement then\n        return 0\n    end\n\n    -- Calculate potency.\n    local power = utils.clamp(player:getSkillLevel(xi.skill.SUMMONING_MAGIC), 0, 700)                      -- Skill\n    power       = math.floor(power * 1.05 + player:getMod(xi.mod.ENHANCES_ELEMENTAL_SIPHON) - 55)          -- Gear\n    power       = math.floor(power * xi.spells.damage.calculateDayAndWeather(player, spiritElement, true)) -- Day and Weather bonuses (Forced)\n    power       = math.floor(power + player:getJobPointLevel(xi.jp.ELEMENTAL_SIPHON_EFFECT) * 3)           -- Job Points\n\n    -- Enforce special limits (player and spirit mp)\n    power = utils.clamp(power, 0, spirit:getMP())                     -- Cap MP drained at spirit's MP\n    power = utils.clamp(power, 0, player:getMaxMP() - player:getMP()) -- Cap MP drained at the max MP - current MP\n\n    spirit:delMP(power)\n\n    return player:addMP(power)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/embolden.lua"]={["Path"]="scripts/actions/abilities/embolden.lua",["SHA256"]="ce2015546ea1d08c519d4416e050dfeaa477ea1ed177a4cafe355cf01a7c3407",["Text"]="-----------------------------------\n-- Ability: Embolden\n-- Enhances the effects of the next enhancing magic spell you cast, but reduces effect duration.\n-- Obtained: Rune Fencer Level 60\n-- Recast Time: 10:00\n-- Duration: 1:00 or first absorb\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    target:addStatusEffect(xi.effect.EMBOLDEN, { duration = 60, origin = player }) -- effects handled in scripts/globals/spells/spell_enhancing.lua\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/enlightenment.lua"]={["Path"]="scripts/actions/abilities/enlightenment.lua",["SHA256"]="3515b8302518ff5e52375d618c16b14d86a6431ef4c2ededac8ead51cac1924d",["Text"]="-----------------------------------\n-- Ability: Enlightenment\n-- Your next spell cast may be any from your list regardless of addenda.\n-- Obtained: Scholar Level 75\n-- Recast Time: 0:05:00\n-- Duration: 0:01:00 or 1 Spell, whichever occurs first\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.ENLIGHTENMENT) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    local merit = (player:getMerit(xi.merit.ENLIGHTENMENT) - 5)\n    player:addStatusEffect(xi.effect.ENLIGHTENMENT, { power = merit, duration = 60, origin = player })\n\n    return xi.effect.ENLIGHTENMENT\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/enmity_douse.lua"]={["Path"]="scripts/actions/abilities/enmity_douse.lua",["SHA256"]="0fb67904e16deb2d13d5fb026af6d36785067d2d070b69edf69fa16d1c54bdbc",["Text"]="-----------------------------------\n-- Ability: Enmity Douse\n-- Description: Reduces the target's enmity towards you.\n-- Obtained: BLM Level 87\n-- Recast Time: 0:10:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    xi.job_utils.black_mage.useEnmityDouse(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/entrust.lua"]={["Path"]="scripts/actions/abilities/entrust.lua",["SHA256"]="c886b05287444a1f1d9d04c8ed32d497effcfe540366cb8b76404efdbf3d5b36",["Text"]="-----------------------------------\n-- Ability: Entrust\n-- Causes the next indicolure spell cast to be able to target a party member.\n-- Obtained: Geomancer Level 75\n-- Recast Time: 00:10:00\n-- Duration: 00:00:30\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.ENTRUST, { power = 1, duration = 60, origin = player })\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/equanimity.lua"]={["Path"]="scripts/actions/abilities/equanimity.lua",["SHA256"]="2750a0257e2f422eae562ebd7ad82c8a478062090866ed29a2fd0740a0b6e0de",["Text"]="-----------------------------------\n-- Ability: Equanimity\n-- Your next black magic spell will generate less enmity.\n-- Obtained: Scholar Level 75\n-- Recast Time: Stratagem Charge\n-- Duration: 1 black magic spell or 60 seconds, whichever occurs first\n--\n-- Level   |Charges |Recharge Time per Charge\n-- -----   -------- ---------------\n-- 10      |1       |4:00 minutes\n-- 30      |2       |2:00 minutes\n-- 50      |3       |1:20 minutes\n-- 70      |4       |1:00 minute\n-- 90      |5       |48 seconds\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    if player:hasStatusEffect(xi.effect.EQUANIMITY) then\n        return xi.msg.basic.EFFECT_ALREADY_ACTIVE, 0\n    end\n\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.EQUANIMITY, { power = player:getMerit(xi.merit.EQUANIMITY), duration = 60, origin = player })\n\n    return xi.effect.EQUANIMITY\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/evokers_roll.lua"]={["Path"]="scripts/actions/abilities/evokers_roll.lua",["SHA256"]="8163261571e94b2cd294c0d35241f755c6010c8c14e4bfb1534a2b33708ae554",["Text"]="-----------------------------------\n-- Ability: Evoker's Roll\n-- Gradually restores MP for party members within area of effect\n-- Optimal Job: Summoner\n-- Lucky Number: 5\n-- Unlucky Number: 9\n-- Level: 40\n-- Phantom Roll +1 Value: 1\n--\n-- Die Roll    |No SMN  |With SMN\n-- --------    -------  -----------\n-- 1           |+1      |+2\n-- 2           |+1      |+2\n-- 3           |+1      |+2\n-- 4           |+1      |+2\n-- 5           |+3      |+4\n-- 6           |+2      |+3\n-- 7           |+2      |+3\n-- 8           |+2      |+3\n-- 9           |+1      |+2\n-- 10          |+3      |+4\n-- 11          |+4      |+5\n-- Bust        |-1      |-1\n--\n-- Busting on Evoker's Roll will give you -1MP/tick less on your own total MP refreshed i.e. you do not actually lose MP\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/familiar.lua"]={["Path"]="scripts/actions/abilities/familiar.lua",["SHA256"]="e6cc05b3ab2061a25832773da3a5b4485597d9c8492c0b9a0d2c4630893ca925",["Text"]="-----------------------------------\n-- Ability: Familiar\n-- Enhances your pet's powers and increases the duration of Charm.\n-- Obtained: Beastmaster Level 1\n-- Recast Time: 1:00:00\n-- Duration: 0:30:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkFamiliar(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.beastmaster.useFamiliar(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/fan_dance.lua"]={["Path"]="scripts/actions/abilities/fan_dance.lua",["SHA256"]="edb440f0e43092e318d4ac94966af81f0bb8b5ca1bd3e45227b7f440588e1e83",["Text"]="-----------------------------------\n-- Ability: Fan Dance\n-- Reduces physical damage taken and increases enmity but renders Samba unusable. Physical damage reduction gradually decreases with each hit taken.\n-- Obtained: Dancer Level 75 Merit Group 2\n-- Recast Time: 3 minutes\n-- Duration: 5 minutes\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    player:addStatusEffect(xi.effect.FAN_DANCE, { power = 9000, duration = 300, origin = player })\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/fealty.lua"]={["Path"]="scripts/actions/abilities/fealty.lua",["SHA256"]="e713005465ec90474315c73e08351af06674101ee2b361a807930e4686cb54a4",["Text"]="-----------------------------------\n-- Ability: Fealty\n-- Grants a powerful resistance to enfeebling magic.\n-- Obtained: Paladin Level 75\n-- Recast Time: 0:10:00\n-- Duration: 0:01:00\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.paladin.useFealty(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/feather_step.lua"]={["Path"]="scripts/actions/abilities/feather_step.lua",["SHA256"]="50dbbedf0d446b9e77c77dc793519d8902ad529ba4fdfe387be6f9cd4d0b73ba",["Text"]="-----------------------------------\n-- Ability: Feather Step\n-- Description Lowers a target's critical hit evasion. If successful, will earn you a finishing move.\n-- Obtained: DNC Level 83\n-- Recast Time: 00:00:05 (Step)\n-- Duration: 00:01:00\n-- Cost: 100TP\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.dancer.checkStepAbility(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.dancer.useStepAbility(player, target, ability, action, xi.effect.BEWILDERED_DAZE_1)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/feint.lua"]={["Path"]="scripts/actions/abilities/feint.lua",["SHA256"]="3c41542aa30611e7b0c0fa9e6aacddca8cd18fab013ab119ae18b9a006494048",["Text"]="-----------------------------------\n-- Ability: Feint\n-- Reduces targets evasion by -150 (Assassin's Culottes +2 Aug: -10 more eva per merit)\n-- Obtained: Thief Level 75\n-- Recast Time: 2:00 minutes\n-- Duration: 1:00 minutes\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return 0, 0\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.thief.useFeint(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/feral_howl.lua"]={["Path"]="scripts/actions/abilities/feral_howl.lua",["SHA256"]="d25430f98841f8f7afee34f0f031b7319a7cc635ca19dbfe1459b7ddb82b4087",["Text"]="-----------------------------------\n-- Ability: Feral Howl\n-- Terrorizes the target.\n-- Obtained: Beastmaster Level 75\n-- Recast Time: 0:05:00\n-- Duration: Apprx. 0:00:01 - 0:00:10\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkFeralHowl(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.job_utils.beastmaster.useFeralHowl(player, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/fight.lua"]={["Path"]="scripts/actions/abilities/fight.lua",["SHA256"]="e2fc8944c3072b1402b18f9555eeb3c00f01921bc1711a3b0863d08e2df245df",["Text"]="-----------------------------------\n-- Ability: Fight\n-- Commands your pet to attack the target.\n-- Obtained: Beastmaster Level 1\n-- Recast Time: 10 seconds\n-- Duration: N/A\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.beastmaster.checkFight(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability)\n    return xi.job_utils.beastmaster.useFight(player, target, ability)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/fighters_roll.lua"]={["Path"]="scripts/actions/abilities/fighters_roll.lua",["SHA256"]="9843a25b4d3ab9641255411581221bf7487ed1a49e0e1af0cd71e0026e3a083c",["Text"]="-----------------------------------\n-- Ability: Fighter's Roll\n-- Improves \"Double Attack\" rate for party members within area of effect\n-- Optimal Job: Warrior\n-- Lucky Number: 5\n-- Unlucky Number: 9\n-- Level: 49\n-- Phantom Roll +1 Value: 1\n--\n-- Die Roll    |No WAR  |With WAR\n-- --------    -------- -----------\n-- 1           |2%      |8%\n-- 2           |2%      |8%\n-- 3           |3%      |9%\n-- 4           |4%      |10%\n-- 5           |12%     |18%\n-- 6           |5%      |11%\n-- 7           |6%      |12%\n-- 8           |7%      |13%\n-- 9           |1%      |7%\n-- 10          |9%      |15%\n-- 11          |18%     |24%\n-- 12+         |-6%     |-6%\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.job_utils.corsair.onRollAbilityCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(caster, target, ability, action)\n    return xi.job_utils.corsair.onRollUseAbility(caster, target, ability, action)\nend\n\nreturn abilityObject\n"},["scripts/actions/abilities/fire_maneuver.lua"]={["Path"]="scripts/actions/abilities/fire_maneuver.lua",["SHA256"]="bbe90cf055b40896eb6cabd76b128460a73fc6383d1ea2bceb0ec143e6ff80b0",["Text"]="-----------------------------------\n-- Ability: Fire Maneuver\n-- Enhances the effect of fire attachments. Must have animator equipped.\n-- Obtained: Puppetmaster level 1\n-- Recast Time: 10 seconds (shared with all maneuvers)\n-- Duration: 1 minute\n-----------------------------------\n---@type TAbility\nlocal abilityObject = {}\n\nabilityObject.onAbilityCheck = function(player, target, ability)\n    return xi.automaton.onManeuverCheck(player, target, ability)\nend\n\nabilityObject.onUseAbility = function(player, target, ability, action)\n    return xi.automaton.onUseManeuver(player, target, ability, action)\nend\n\nreturn abilityObject\n"}};
